def main():
    p=ROOT/'translation/table_expansion_449.review.json';assert not p.exists()
    cat=read(ROOT/'translation/tables.catalog.working.json');refs=defaultdict(list)
    for r in cat:
        if r['translation']:refs[r['original']].append(r)
    entries=[];audit=[]
    for r in cat:
        if r['translation'] or r['original'] not in T:continue
        existing=refs[r['original']];variants={x['translation'] for x in existing}
        text=next(iter(variants)) if len(variants)==1 else T[r['original']]
        if len(variants)==1:audit.append(dict(key=r['key'],reference=existing[0]['key'],translation=text))
        entries.append(dict(r,translation=text,status='draft_table_reviewed'))
    assert len(entries)==135,len(entries)
    write(p,dict(entries=entries,reuse_audit=audit,review_notes=['扩展严格固定表解析后新增135个设施/菜单文本，32字节完整文本行及44字节帮助行（前8字节元数据、32字节文本、后4字节元数据）。','全部文本经过CP932解码、NUL边界和成员结构校验；不把技能属性表等ASCII内部名称视为可翻译文字。','同原文且译文唯一的已有固定表条目优先复用；其余按既有术语补译。保持所有数字和数据区不变。']))
    print('New table rows:',len(entries),'existing exact reuse:',len(audit))
if __name__=='__main__':main()
